-- Group mutation runs produced by one "Sweep" experiment. Each swept variant
-- still flows through the normal single-mutation pipeline (so it is logged and
-- gets a structural-consistency score); they simply share a sweep_id.

alter table public.mutation_runs
  add column if not exists sweep_id uuid;

create index if not exists mutation_runs_sweep_id_idx
  on public.mutation_runs (sweep_id);

comment on column public.mutation_runs.sweep_id is
  'Shared id for all runs generated by one Sweep experiment. NULL for single ad-hoc predictions.';
